with (P/'references.bib').open('w') as f:
 for r in refs:
    f.write('@'+r['kind']+'{'+r['key']+',\n')
    for k in ['author','title','year','journal','booktitle','series','volume','number','pages','publisher','doi','url','eprint','archivePrefix']:
      if k in r:f.write('  '+k+' = {'+str(r[k])+'},\n')
    f.write('  note = {verified},\n  annotation = {'+r['checked'].replace('{','(').replace('}',')')+'}\n}\n\n')
(P/'reference_checks.json').write_text(json.dumps(refs,ensure_ascii=False,indent=2)+'\n')
